package com.desktodo.app;
import android.app.*;import android.widget.*;import android.graphics.*;import android.text.InputType;import org.json.*;import java.util.Base64;
/** First-run path; Wi-Fi password never enters drafts, preferences, model context or logs. */
final class SetupPanel {
 final MainActivity a;int step=0;TextView live;JSONObject autonomous;
 SetupPanel(MainActivity a){this.a=a;}
 void update(){if(live!=null)live.setText(a.message);}
 void render(){LinearLayout l=a.card("把工作台，放进你的日常");l.addView(a.text("连接 → 配网 → 选桌面 → 自主更新 → 记一件事",14,a.muted));live=a.text(a.message,14,a.green);l.addView(live);
 switch(step){case 0:l.addView(a.text("第一步 · 找到你的屏幕",23,a.ink));l.addView(a.text("开启手机蓝牙，靠近工作台。首次配网请使用2.4GHz Wi-Fi；蓝牙只负责发现和加密配网。",14,a.muted));a.primary(l,"通过蓝牙发现工作台",()->a.scan());EditText address=a.field(l,"已有设备地址（可选）",a.origin);a.button(l,"按地址连接",()->{try{a.origin=DeskModel.normalizeOrigin(address.getText().toString());a.persist();a.connect();}catch(Exception e){a.toast(e.getMessage());}});a.button(l,"设备已连接，继续",()->{if(!a.connected){a.toast("可直接进入下一步配网，再自动读取设备地址");}step=1;a.draw();});break;
 case 1:l.addView(a.text("第二步 · 接入Wi-Fi",23,a.ink));l.addView(a.text("已连网可跳过。更换网络时按住工作台BOOT键两秒，随后五分钟内发送配置。密码只通过系统加密蓝牙发送；失败会回到原网络。",14,a.muted));EditText name=a.field(l,"2.4GHz Wi-Fi名称","");l.addView(a.text("Wi-Fi密码（开放网络留空）",13,a.muted));EditText password=new EditText(a);password.setHint("仅本次加密传输");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setSaveEnabled(false);password.setMinimumHeight(a.dp(52));l.addView(password);a.primary(l,"加密发送配网信息",()->{try{for(String permission:android.os.Build.VERSION.SDK_INT>=31?new String[]{"android.permission.BLUETOOTH_SCAN","android.permission.BLUETOOTH_CONNECT"}:new String[]{"android.permission.ACCESS_FINE_LOCATION"})if(a.checkSelfPermission(permission)!=0){a.requestPermissions(android.os.Build.VERSION.SDK_INT>=31?new String[]{"android.permission.BLUETOOTH_SCAN","android.permission.BLUETOOTH_CONNECT"}:new String[]{"android.permission.ACCESS_FINE_LOCATION"},21);return;}String ssid=name.getText().toString(),pass=password.getText().toString();a.discovery.provision(ssid,pass);password.setText("");}catch(Exception e){a.toast(e.getMessage());}});a.button(l,"已连接，继续选择桌面",()->{if(!a.connected){a.toast("请等待读取到工作台地址");return;}step=2;a.draw();});break;
 case 2:l.addView(a.text("第三步 · 选一种桌面",23,a.ink));String[] keys={"work","focus","life"},names={"工作桌面","专注桌面","生活画报"};for(int i=0;i<keys.length;i++){String key=keys[i];a.button(l,names[i]+(a.screen.selected.equals(key)?" ✓":""),()->{a.screen.selected=key;a.draw();});}try{a.screen.preview(l,ScreenData.scene(a.cfg,a.screen.selected));}catch(Exception e){a.toast(e.getMessage());}a.primary(l,"预览并应用（全刷一次）",()->a.screen.apply());a.button(l,"保留当前桌面，继续",()->{if(a.remote==null||a.remote.optBoolean("needs_full")){a.toast("先明确应用一次桌面，建立局刷基准");return;}step=3;a.draw();});break;
 case 3:autonomy(l);a.button(l,"继续，记下第一件事",()->{step=4;a.draw();});break;
 default:l.addView(a.text("最后 · 留下一件重要的事",23,a.ink));l.addView(a.text("完成后它会从屏幕消失。重复事项需要截止时间，完成后只生成下一次。",14,a.muted));a.primary(l,"添加第一条待办",()->a.edit(-1));a.button(l,"完成配置，进入工作台",()->{a.prefs.edit().putBoolean("setupDone",true).apply();a.openPage("工作台");});break;}
 if(step>0)a.button(a.body,"返回上一步",()->{step--;a.draw();});}
 static String cityBitmap(String city){Bitmap image=Bitmap.createBitmap(128,20,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(image);c.drawColor(Color.WHITE);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.BLACK);p.setTextSize(16);p.setTypeface(ScreenFonts.chinese);String label=city;while(label.length()>1&&p.measureText(label)>128)label=label.substring(0,label.length()-1);c.drawText(label,0,-p.ascent(),p);byte[] bytes=new byte[320];for(int y=0;y<20;y++)for(int x=0;x<128;x++)if(Color.red(image.getPixel(x,y))>=160)bytes[y*16+x/8]|=(byte)(128>>(x%8));image.recycle();return Base64.getEncoder().encodeToString(bytes);}
 void autonomy(LinearLayout l){l.addView(a.text("手机离开，屏幕继续工作",23,a.ink));l.addView(a.text("开启后由ESP32按分钟局刷时钟，每10分钟直接获取一次"+a.cfg.optString("city","苏州")+"天气；数据未变不刷。天气区使用设备自己的简洁排版，其他区域保持。设备需持续供电和联网。",14,a.muted));l.addView(a.text("断网保留缓存，过期标识旧天气；重启后仍需明确应用一次布局建立基准。日历、股票及卡片尚不由设备自行获取。",13,a.muted));if(autonomous!=null)l.addView(a.text((autonomous.optBoolean("enabled")?"自主更新已开启":"自主更新未开启")+" · "+(autonomous.optBoolean("weather_available")?"天气缓存可用":"等待设备获取天气"),15,a.green));a.primary(l,"开启时钟与天气自主更新",()->saveAutonomy(true));a.button(l,"关闭自主更新",()->saveAutonomy(false));a.button(l,"读取设备运行状态",this::readAutonomy);}
 void autonomyPage(){autonomy(a.card("自主运行"));}
 void readAutonomy(){if(!a.connected){a.toast("请先连接设备");return;}final JSONObject[] result={null};a.work("读取自主更新状态",()->result[0]=DeskApi.json(a.origin+"/api/local/autonomy"),()->{autonomous=result[0];a.message="设备运行状态已更新";});}
 void saveAutonomy(boolean enabled){if(!a.connected){a.toast("请先连接设备");return;}try{JSONObject value=new JSONObject().put("enabled",enabled).put("latitude",a.cfg.getDouble("latitude")).put("longitude",a.cfg.getDouble("longitude")).put("city_bitmap",cityBitmap(a.cfg.optString("city","苏州")));final String destination=a.origin;final JSONObject[] result={null};a.work("保存自主更新设置",()->{DeskApi.request(destination+"/api/local/autonomy","POST",value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),"application/json");result[0]=DeskApi.json(destination+"/api/local/autonomy");},()->{autonomous=result[0];a.message="自主更新设置已保存到工作台";});}catch(Exception e){a.toast(e.getMessage());}}
}
